// Ověří podpis příchozího webhooku z aplikace.
// Podpis: hex(HMAC-SHA256(FOODTAB_WEBHOOK_SECRET, timestamp + "." + telo)),
// okno 5 minut proti přehrání — stejně jako overitPodpisWebhooku v aplikaci.
//
// POZOR: uzel Webhook tělo rozparsuje a my ho tady serializujeme znovu.
// Funguje to, protože aplikace posílá JSON.stringify bez mezer a Node
// zachová pořadí klíčů. Kdyby aplikace tělo někdy formátovala jinak,
// zapněte v uzlu Webhook volbu Raw Body a počítejte HMAC nad ním.
const crypto = require('crypto');
const vstup = $input.first().json;
const hlavicky = vstup.headers || {};
const secret = $env.FOODTAB_WEBHOOK_SECRET;
if (!secret) throw new Error('Chybí proměnná prostředí FOODTAB_WEBHOOK_SECRET — bez ní nejde podpis ověřit.');
const ts = String(hlavicky['x-foodtab-timestamp'] || '');
const podpis = String(hlavicky['x-foodtab-signature'] || '');
if (!ts || !podpis) throw new Error('Chybí hlavička X-FoodTab-Timestamp nebo X-FoodTab-Signature.');
if (!Number.isFinite(Number(ts)) || Math.abs(Date.now() / 1000 - Number(ts)) > 300) {
  throw new Error('Časová značka je mimo okno 5 minut (nesynchronizované hodiny nebo přehraný požadavek).');
}
const telo = JSON.stringify(vstup.body || {});
const ocekavany = crypto.createHmac('sha256', secret).update(ts + '.' + telo).digest('hex');
const a = Buffer.from(ocekavany, 'utf8');
const b = Buffer.from(podpis, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Neplatný podpis webhooku.');
const zprava = vstup.body || {};
return [{ json: { typ: zprava.type || '', klicUdalosti: String(hlavicky['x-foodtab-idempotency-key'] || zprava.idempotencyKey || ''), organizationId: zprava.organizationId || null, payload: zprava.payload || {} } }];

// Vytáhne z události počet pokusů a strop. Když chybí, bere se 1 a 5
// (stejné výchozí hodnoty jako publish_jobs.max_attempts).
const vstup = $input.first().json;
const p = vstup.payload || {};
const attempts = Number(p.attempts != null ? p.attempts : 1);
const maxAttempts = Number(p.maxAttempts != null ? p.maxAttempts : (p.max_attempts != null ? p.max_attempts : 5));
return [{ json: {
  jobId: p.publishJobId || p.jobId || p.id || '',
  contentItemId: p.contentItemId || '',
  chyba: p.error || p.lastError || '',
  attempts: Number.isFinite(attempts) ? attempts : 1,
  maxAttempts: Number.isFinite(maxAttempts) ? maxAttempts : 5,
  klicUdalosti: vstup.klicUdalosti || '',
} }];
